import { useState } from 'react'
import { supabase } from '@/lib/supabaseClient'
import { mapBookingError } from '@/lib/booking'
import { useAuth } from '@/hooks/useAuth'
import type { Booking } from '@/types/database.types'

/**
 * Creates a booking request (Phase 6).
 *
 * The insert deliberately sends total_price = 0: the database trigger
 * compute_booking_total() overwrites it server-side (days × price_per_day),
 * so a tampered client can never influence the price. The booking number
 * (CF-YYYY-NNNN) is also generated by the database. RLS enforces
 * pending/unpaid status and available caftan on insert.
 */
type CreateBookingInput = {
  caftanId: string
  startDate: string
  endDate: string
  customerNotes: string
}

type CreateBookingResult = {
  booking: Booking | null
  /** Translation key for display, or null on success */
  errorKey: string | null
}

export function useCreateBooking() {
  const { session } = useAuth()
  const [submitting, setSubmitting] = useState(false)

  async function createBooking(input: CreateBookingInput): Promise<CreateBookingResult> {
    if (!supabase) {
      return { booking: null, errorKey: 'booking.error_generic' }
    }
    if (!session) {
      // Session expired between page load and submit — ask to sign in again.
      return { booking: null, errorKey: 'errors.session_expired' }
    }
    setSubmitting(true)
    const { data, error } = await supabase
      .from('bookings')
      .insert({
        caftan_id: input.caftanId,
        customer_id: session.user.id,
        start_date: input.startDate,
        end_date: input.endDate,
        customer_notes: input.customerNotes,
        total_price: 0, // overwritten by the compute_booking_total trigger
      })
      .select()
      .single()
    setSubmitting(false)

    if (error) {
      return { booking: null, errorKey: mapBookingError(error) }
    }
    return { booking: data, errorKey: null }
  }

  return { createBooking, submitting }
}
